from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE

prs = Presentation("/root/input.pptx")

for i, slide in enumerate(prs.slides):
    print(f"--- Slide {i+1} ---")
    for shape in slide.shapes:
        print(f"Shape: {shape.name}, Type: {shape.shape_type}")
        if shape.has_text_frame:
            print(f"  Text: {shape.text}")
        if shape.shape_type == MSO_SHAPE_TYPE.EMBEDDED_OLE_OBJECT:
            print("  Found Embedded OLE Object")

from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE
import openpyxl
import io

prs = Presentation("/root/input.pptx")

excel_blob = None
for slide in prs.slides:
    for shape in slide.shapes:
        if shape.shape_type == MSO_SHAPE_TYPE.EMBEDDED_OLE_OBJECT:
            if "Worksheet" in shape.ole_format.prog_id or "Excel" in shape.ole_format.prog_id:
                excel_blob = shape.ole_format.blob
                break
    if excel_blob:
        break

if excel_blob:
    # Save to disk for inspection (optional, but good for debugging)
    with open("/root/temp_embedded.xlsx", "wb") as f:
        f.write(excel_blob)

    # Load with openpyxl
    wb = openpyxl.load_workbook(io.BytesIO(excel_blob))
    ws = wb.active

    print("--- Excel Content ---")
    for row in ws.iter_rows(max_row=5, values_only=True):
        print(row)
else:
    print("No embedded Excel found.")
